"use client";

import { Component, type FC, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { findBlock, hiddenBlocks, type BlockContext } from "./registry";

/**
 * Models write almost-JSON. Repair the usual slips before giving up:
 * trailing commas and raw line breaks inside strings.
 */
export const sanitizeJSON = (jsonString: string): string => {
  return jsonString
    // Remove trailing commas before closing braces/brackets
    .replace(/,(\s*[}\]])/g, "$1")
    // Escape literal newlines that sit inside a quoted string
    .split("\n")
    .map((line, i, arr) => {
      if (i === 0) return line;
      const prevLines = arr.slice(0, i).join("\n");
      const quoteCount = (prevLines.match(/(?<!\\)"/g) || []).length;
      return quoteCount % 2 !== 0 ? "\\n" + line : line;
    })
    .join("");
};

export type ParsedBlock =
  | { ok: true; data: any }
  | { ok: false; error: string };

export const parseBlock = (code: string): ParsedBlock => {
  try {
    return { ok: true, data: JSON.parse(code) };
  } catch (firstError) {
    try {
      return { ok: true, data: JSON.parse(sanitizeJSON(code)) };
    } catch {
      return { ok: false, error: (firstError as Error).message };
    }
  }
};

/** A block that throws must not take the whole message down with it. */
class BlockBoundary extends Component<
  { children: ReactNode; fallback: ReactNode; resetKey: string },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidUpdate(prev: { resetKey: string }) {
    if (prev.resetKey !== this.props.resetKey && this.state.failed) {
      this.setState({ failed: false });
    }
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

export const BlockSkeleton: FC<{ className?: string }> = ({ className }) => (
  <div
    className={cn(
      "h-28 w-full max-w-2xl animate-pulse rounded-2xl border bg-muted/60",
      className,
    )}
    aria-hidden
  />
);

export interface BlockRendererProps extends Partial<BlockContext> {
  /** The fence language: `plan`, `chart`, ... */
  type: string;
  /** The raw text inside the fence. */
  code: string;
  /** Shown while the JSON is incomplete (streaming) or invalid. Defaults to nothing. */
  fallback?: ReactNode;
  className?: string;
}

const noop = () => {};

/**
 * Turns one fenced block into its component.
 * Pure: no chat runtime, no network. Give it `send` to make interactive blocks talk back.
 */
export const BlockRenderer: FC<BlockRendererProps> = ({
  type,
  code,
  send = noop,
  isLatest = true,
  fallback = null,
  className,
}) => {
  if (hiddenBlocks.includes(type)) return null;

  const block = findBlock(type);
  if (!block) return null;

  const parsed = parseBlock(code);
  if (!parsed.ok) return <>{fallback}</>;

  return (
    <BlockBoundary fallback={fallback} resetKey={code}>
      <div className={cn("not-prose my-4", className)} data-block={block.name}>
        {block.render(parsed.data, { send, isLatest })}
      </div>
    </BlockBoundary>
  );
};

"use client";

import { FC } from "react";
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, XAxis, YAxis } from "recharts";
import { ChartContainer, ChartTooltip, ChartTooltipContent, ChartConfig } from "@/components/ui/chart";
import type { SerializableChart } from "./schema";
import { cn } from "@/lib/utils";

interface ChartProps extends SerializableChart {
  className?: string;
  onDataPointClick?: (dataPoint: any) => void;
}

export const Chart: FC<ChartProps> = ({
  id,
  type,
  title,
  description,
  data,
  xKey,
  series,
  showLegend = true,
  showGrid = true,
  className,
  onDataPointClick,
}) => {
  // Build ChartConfig from series
  const chartConfig: ChartConfig = series.reduce((config, s) => {
    config[s.key] = {
      label: s.label,
      color: s.color,
    };
    return config;
  }, {} as ChartConfig);

  // Default colors for series without explicit colors
  const defaultColors = [
    "hsl(var(--chart-1))",
    "hsl(var(--chart-2))",
    "hsl(var(--chart-3))",
    "hsl(var(--chart-4))",
    "hsl(var(--chart-5))",
  ];

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-tool-ui-id={id}
      data-slot="chart"
    >
      {(title || description) && (
        <div className="space-y-1">
          {title && <h3 className="text-lg font-semibold">{title}</h3>}
          {description && <p className="text-sm text-muted-foreground">{description}</p>}
        </div>
      )}

      <ChartContainer id={id} config={chartConfig}>
        {type === "bar" ? (
          <BarChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Bar
                key={s.key}
                dataKey={s.key}
                fill={s.color || defaultColors[index % defaultColors.length]}
                radius={[4, 4, 0, 0]}
              />
            ))}
          </BarChart>
        ) : (
          <LineChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Line
                key={s.key}
                type="monotone"
                dataKey={s.key}
                stroke={s.color || defaultColors[index % defaultColors.length]}
                strokeWidth={2}
                dot={{ r: 3 }}
                activeDot={{ r: 5 }}
              />
            ))}
          </LineChart>
        )}
      </ChartContainer>
    </div>
  );
};

export { Chart } from "./chart";
export { parseSerializableChart } from "./schema";
export type { SerializableChart, ChartSeries } from "./schema";

export interface ChartSeries {
  key: string;
  label: string;
  color?: string;
}

export interface SerializableChart {
  id: string;
  type: "bar" | "line";
  title?: string;
  description?: string;
  data: Record<string, any>[];
  xKey: string;
  series: ChartSeries[];
  showLegend?: boolean;
  showGrid?: boolean;
}

export function parseSerializableChart(data: any): SerializableChart {
  // Check if data is in the dataSeries format with x/y objects
  if (data.dataSeries?.[0]?.data?.[0]?.x !== undefined) {
    // Transform dataSeries[].data[{x,y}] format to expected format
    const firstSeries = data.dataSeries[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.dataSeries.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.dataSeries.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.categories and series[].data
  if (data.xAxis?.categories && data.series?.[0]?.data) {
    // Transform xAxis.categories + series[].data format to expected format
    const xValues = data.xAxis.categories || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.values and series[].values (camelCase)
  if (data.xAxis?.values && data.series?.[0]?.values) {
    // Transform xAxis.values + series[].values format to expected format
    const xValues = data.xAxis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with x_axis/y_axis/series.values (snake_case)
  if (data.x_axis && data.series?.[0]?.values) {
    // Transform alternative format to expected format
    const xValues = data.x_axis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the series[].data[{x, y}] format (similar to dataSeries but uses 'series')
  if (data.series?.[0]?.data?.[0]?.x !== undefined) {
    // Transform series[].data[{x,y}] format to expected format
    const firstSeries = data.series[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || data.series?.[0]?.type || "bar",
      title: data.title || data.xAxisTitle,
      description: data.description || data.yAxisTitle,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Standard format
  return {
    id: data.id || crypto.randomUUID(),
    type: data.type || "bar",
    title: data.title,
    description: data.description,
    data: data.data || [],
    xKey: data.xKey || "x",
    series: data.series || [],
    showLegend: data.showLegend ?? true,
    showGrid: data.showGrid ?? true,
  };
}

"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import * as LucideIcons from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Chart } from "@/components/tool-ui/chart";
import type { SerializableDashboard, MetricTile, ChartTile, StatComparisonTile, ProgressTile } from "./schema";

interface DashboardProps extends SerializableDashboard {
  className?: string;
}

// Get tile size class for flex layout (tiles auto-fill available space)
const getTileSizeClass = (size: string = "small", columns: number = 2) => {
  switch (size) {
    case "large":
      // Large tiles take full width
      return "w-full";
    case "medium":
      // Medium tiles flex to fill space
      if (columns === 1) return "w-full";
      return "flex-1 min-w-full md:min-w-[300px]";
    case "small":
    default:
      // Small tiles flex to fill space
      if (columns === 1) return "w-full";
      return "flex-1 min-w-full md:min-w-[200px]";
  }
};

// Metric Tile Component
const MetricTileComponent: FC<{ tile: MetricTile; columns: number }> = ({ tile, columns }) => {
  const trendIcon = tile.trend === "up"
    ? <LucideIcons.TrendingUp className="w-3 h-3" />
    : tile.trend === "down"
    ? <LucideIcons.TrendingDown className="w-3 h-3" />
    : <LucideIcons.Minus className="w-3 h-3" />;

  const trendColor = tile.trend === "up"
    ? "text-green-600 dark:text-green-400"
    : tile.trend === "down"
    ? "text-red-600 dark:text-red-400"
    : "text-muted-foreground";

  const Icon = tile.icon ? (LucideIcons as any)[tile.icon] : null;

  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-2">
        {Icon && (
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white dark:bg-black mb-1">
            <Icon className="h-5 w-5 text-black dark:text-white" />
          </div>
        )}
        <div className="space-y-0.5">
          <p className="text-xs font-medium text-muted-foreground">
            {tile.label}
          </p>
          <div className="flex items-baseline gap-1.5">
            <p className="text-md font-bold tracking-tight">
              {tile.value}
            </p>
            {tile.delta && tile.trend && (
              <div className={cn("flex items-center gap-0.5 text-xs font-medium", trendColor)}>
                {trendIcon}
                <span>{tile.delta}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Chart Tile Component
const ChartTileComponent: FC<{ tile: ChartTile; columns: number }> = ({ tile, columns }) => {
  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <Chart {...tile.chart} />
    </div>
  );
};

// Stat Comparison Tile Component
const StatComparisonTileComponent: FC<{ tile: StatComparisonTile; columns: number }> = ({ tile, columns }) => {
  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-3">
        <p className="text-xs font-semibold text-muted-foreground">
          {tile.label}
        </p>
        <div className="flex items-center justify-around gap-3">
          {tile.stats.map((stat, index) => (
            <div key={index} className="flex flex-col items-center gap-0.5">
              <p className="text-[10px] text-muted-foreground">{stat.label}</p>
              <p className="text font-bold">{stat.value}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Progress Tile Component
const ProgressTileComponent: FC<{ tile: ProgressTile; columns: number }> = ({ tile, columns }) => {
  const percentage = tile.percentage ?? (tile.max > 0 ? (tile.value / tile.max) * 100 : 0);
  const showPercentage = tile.showPercentage ?? true;

  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <p className="text-xs font-semibold text-muted-foreground">
            {tile.label}
          </p>
          {showPercentage && (
            <p className="text-xs font-bold">
              {Math.round(percentage)}%
            </p>
          )}
        </div>
        <Progress value={percentage} className="h-1.5" />
        <div className="flex items-center justify-between text-[10px] text-muted-foreground">
          <span>{tile.value.toLocaleString()}</span>
          <span>{tile.max.toLocaleString()}</span>
        </div>
      </div>
    </div>
  );
};

// Main Dashboard Component
export const Dashboard: FC<DashboardProps> = ({
  id,
  title,
  description,
  tiles,
  columns = 2,
  className,
}) => {
  const flexClass = cn(
    "flex flex-wrap gap-3"
  );

  return (
    <div
      className={cn("space-y-3", className)}
      data-tool-ui-id={id}
      data-slot="dashboard"
    >
      {/* Header */}
      {(title || description) && (
        <div className="space-y-0.5">
          {title && (
            <h3 className="text-base font-semibold tracking-tight">
              {title}
            </h3>
          )}
          {description && (
            <p className="text-xs text-muted-foreground">
              {description}
            </p>
          )}
        </div>
      )}

      {/* Tiles Flex Container */}
      <div className={flexClass}>
        {tiles.map((tile) => {
          switch (tile.type) {
            case "metric":
              return <MetricTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "chart":
              return <ChartTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "stat-comparison":
              return <StatComparisonTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "progress":
              return <ProgressTileComponent key={tile.id} tile={tile} columns={columns} />;
            default:
              return null;
          }
        })}
      </div>
    </div>
  );
};

export { Dashboard } from "./dashboard";
export {
  parseSerializableDashboard,
  type SerializableDashboard,
  type DashboardTile,
  type MetricTile,
  type ChartTile,
  type StatComparisonTile,
  type ProgressTile,
} from "./schema";

import type { SerializableChart } from "../chart/schema";

// Metric/KPI tile
export interface MetricTile {
  type: "metric";
  id: string;
  label: string;
  value: string | number;
  icon?: string;
  trend?: "up" | "down" | "neutral";
  delta?: string;
  size?: "small" | "medium" | "large";
}

// Chart tile (reuses existing Chart component)
export interface ChartTile {
  type: "chart";
  id: string;
  chart: SerializableChart;
  size?: "small" | "medium" | "large";
}

// Stat comparison tile
export interface StatComparisonTile {
  type: "stat-comparison";
  id: string;
  label: string;
  stats: Array<{ label: string; value: string | number }>;
  size?: "small" | "medium" | "large";
}

// Progress tile
export interface ProgressTile {
  type: "progress";
  id: string;
  label: string;
  value: number;
  max: number;
  percentage?: number;
  showPercentage?: boolean;
  size?: "small" | "medium" | "large";
}

// Discriminated union for tile types
export type DashboardTile = MetricTile | ChartTile | StatComparisonTile | ProgressTile;

// Main dashboard interface
export interface SerializableDashboard {
  id: string;
  title?: string;
  description?: string;
  tiles: DashboardTile[];
  columns?: 1 | 2;
}

export function parseSerializableDashboard(data: any): SerializableDashboard {
  // Helper function to parse trend string to trend type
  const parseTrend = (trendStr?: string): "up" | "down" | "neutral" | undefined => {
    if (!trendStr) return undefined;
    const str = trendStr.toLowerCase();
    if (str.includes('+') || str.includes('↑') || str.includes('positive')) return "up";
    if (str.includes('-') || str.includes('↓') || str.includes('negative')) return "down";
    return "neutral";
  };

  // Handle kpis format (alternative to tiles)
  let tilesData = data.tiles;
  if (!tilesData && data.kpis) {
    tilesData = data.kpis.map((kpi: any) => ({
      type: "metric",
      id: kpi.id || crypto.randomUUID(),
      label: kpi.label,
      value: kpi.value,
      icon: kpi.icon,
      trend: parseTrend(kpi.trend),
      delta: kpi.trend, // The trend string becomes the delta
      size: kpi.size,
    }));
  }

  // Auto-generate IDs for tiles if not provided
  const tiles = (tilesData || []).map((tile: any) => ({
    ...tile,
    id: tile.id || crypto.randomUUID(),
  }));

  // Clamp columns to max 2
  const columns = Math.min(data.columns || 2, 2) as 1 | 2;

  return {
    id: data.id || crypto.randomUUID(),
    title: data.title,
    description: data.description,
    tiles,
    columns,
  };
}

"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Check, X, TrendingUp, TrendingDown, ExternalLink } from "lucide-react";
import type { SerializableDataTable, Column, ColumnFormat } from "./schema";

interface DataTableProps extends SerializableDataTable {
  className?: string;
}

const getToneClass = (tone: string) => {
  switch (tone) {
    case "neutral":
      return "bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200";
    case "info":
      return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200";
    case "success":
      return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200";
    case "warning":
      return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200";
    case "danger":
      return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200";
    default:
      return "bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200";
  }
};

const formatCellValue = (value: any, format?: ColumnFormat): React.ReactNode => {
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground">-</span>;
  }

  if (!format || format.kind === "text") {
    return value;
  }

  switch (format.kind) {
    case "status":
      if (format.statusMap && value in format.statusMap) {
        const config = format.statusMap[value];
        const displayLabel = config.label || value;
        return (
          <span
            className={cn(
              "inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium",
              getToneClass(config.tone)
            )}
          >
            {displayLabel}
          </span>
        );
      }
      return value;

    case "date":
      try {
        const date = new Date(value);
        if (isNaN(date.getTime())) return value;

        if (format.dateFormat === "long") {
          return date.toLocaleDateString("en-US", {
            year: "numeric",
            month: "long",
            day: "numeric",
          });
        } else if (format.dateFormat === "relative") {
          const now = new Date();
          const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);
          const diffInDays = Math.floor(diffInSeconds / 86400);

          if (diffInDays === 0) return "Today";
          if (diffInDays === 1) return "Yesterday";
          if (diffInDays === -1) return "Tomorrow";
          if (diffInDays > 0) return `${diffInDays}d ago`;
          return `in ${Math.abs(diffInDays)}d`;
        } else {
          // short
          return date.toLocaleDateString("en-US", {
            year: "numeric",
            month: "short",
            day: "numeric",
          });
        }
      } catch {
        return value;
      }

    case "boolean":
      return (
        <div className="flex items-center justify-center">
          {value ? (
            <Check className="h-4 w-4 text-green-600 dark:text-green-400" />
          ) : (
            <X className="h-4 w-4 text-red-600 dark:text-red-400" />
          )}
        </div>
      );

    case "number":
      const num = Number(value);
      if (isNaN(num)) return value;

      if (format.numberFormat === "currency") {
        return new Intl.NumberFormat("en-US", {
          style: "currency",
          currency: "USD",
        }).format(num);
      } else if (format.numberFormat === "percentage") {
        return `${(num * 100).toFixed(1)}%`;
      } else if (format.numberFormat === "decimal") {
        return num.toFixed(2);
      } else {
        // integer
        return Math.round(num).toLocaleString();
      }

    case "delta":
      const delta = Number(value);
      if (isNaN(delta)) return value;

      const isPositive = delta > 0;
      const isNegative = delta < 0;
      const showSign = format.showSign ?? true;

      const deltaColors = format.deltaColors || {
        positive: "text-green-600 dark:text-green-400",
        negative: "text-red-600 dark:text-red-400",
        neutral: "text-gray-600 dark:text-gray-400",
      };

      const colorClass = isPositive
        ? deltaColors.positive
        : isNegative
        ? deltaColors.negative
        : deltaColors.neutral;

      return (
        <div className={cn("flex items-center gap-1", colorClass)}>
          {isPositive && <TrendingUp className="h-4 w-4" />}
          {isNegative && <TrendingDown className="h-4 w-4" />}
          <span className="font-medium">
            {showSign && isPositive ? "+" : ""}
            {delta.toFixed(1)}
          </span>
        </div>
      );

    case "link":
      if (!value) return null;
      const url = String(value);
      const target = format.linkTarget || "_blank";
      const isExternal = target === "_blank";

      return (
        <a
          href={url}
          target={target}
          rel={isExternal ? "noopener noreferrer" : undefined}
          className="inline-flex items-center gap-1 text-primary hover:underline"
        >
          <span className="truncate max-w-xs">{url}</span>
          {isExternal && <ExternalLink className="h-3 w-3 flex-shrink-0" />}
        </a>
      );

    case "badge":
      const badgeValue = String(value);
      const badgeColorMap = format.badgeColorMap || {};
      const badgeColor = badgeColorMap[badgeValue] || "bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200";

      return (
        <span
          className={cn(
            "inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium",
            badgeColor
          )}
        >
          {badgeValue}
        </span>
      );

    case "array":
      if (!Array.isArray(value)) return value;

      const maxVisible = format.maxVisibleItems ?? 3;
      const separator = format.separator || ", ";
      const visibleItems = value.slice(0, maxVisible);
      const hiddenCount = value.length - maxVisible;

      return (
        <div className="flex items-center gap-1">
          <span>{visibleItems.join(separator)}</span>
          {hiddenCount > 0 && (
            <span className="text-xs text-muted-foreground">
              +{hiddenCount} more
            </span>
          )}
        </div>
      );

    default:
      return value;
  }
};

export const DataTable: FC<DataTableProps> = ({
  id,
  columns,
  data,
  rowIdKey,
  caption,
  striped = true,
  compact = false,
  className,
}) => {
  const getPriorityClass = (priority?: string) => {
    if (!priority || priority === "primary") return "";
    if (priority === "secondary") return "hidden lg:table-cell";
    if (priority === "tertiary") return "hidden xl:table-cell";
    return "";
  };

  // Split columns into primary and secondary/tertiary for mobile view
  const primaryColumns = columns.filter((col) => !col.priority || col.priority === "primary");
  const secondaryColumns = columns.filter((col) => col.priority === "secondary" || col.priority === "tertiary");

  // Desktop table view
  const tableView = (
    <div className="hidden md:block overflow-x-auto rounded-lg border border-border bg-card">
      <Table>
        {caption && <TableCaption>{caption}</TableCaption>}
        <TableHeader>
          <TableRow>
            {columns.map((column) => (
              <TableHead
                key={column.key}
                className={cn(getPriorityClass(column.priority))}
              >
                {column.label}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={columns.length}
                className="h-24 text-center text-muted-foreground"
              >
                No data available
              </TableCell>
            </TableRow>
          ) : (
            data.map((row, index) => (
              <TableRow
                key={row[rowIdKey] || index}
                className={cn(
                  striped && index % 2 === 0 && "bg-muted/30",
                  compact ? "h-10" : "h-12"
                )}
              >
                {columns.map((column) => (
                  <TableCell
                    key={column.key}
                    className={cn(
                      getPriorityClass(column.priority),
                      compact && "py-2"
                    )}
                  >
                    {formatCellValue(row[column.key], column.format)}
                  </TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );

  // Mobile accordion view
  const mobileView = data.length === 0 ? (
    <div className="md:hidden p-8 text-center text-muted-foreground">
      No data available
    </div>
  ) : (
    <div className="md:hidden bg-card flex flex-col overflow-hidden rounded-2xl border shadow-xs">
      {data.map((row, index) => {
        const rowId = row[rowIdKey] || `row-${index}`;
        const firstColumn = primaryColumns[0];
        const summaryColumns = primaryColumns.slice(1, 3); // Show up to 2 more columns in summary
        const detailColumns = [...primaryColumns.slice(3), ...secondaryColumns];

        return (
          <Accordion
            key={rowId}
            type="single"
            collapsible
            className={cn(index > 0 && "border-t")}
            role="listitem"
            aria-label={`Row ${index + 1}: ${row[firstColumn.key]}`}
          >
            <AccordionItem value={rowId} className="last:border-b-0 group border-0">
              <AccordionTrigger
                className={cn(
                  "focus-visible:border-ring focus-visible:ring-ring/50 flex flex-1 items-start justify-between gap-4 text-left text-sm font-medium transition-all outline-none focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&[data-state=open]>svg]:scale-y-[-1] group-data-[state=closed]:hover:bg-accent/50 active:bg-accent/50 group-data-[state=open]:bg-muted w-full rounded-none px-4 py-3 hover:no-underline"
                )}
                aria-label={`Row ${index + 1}: ${row[firstColumn.key]}. Expand for details`}
              >
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                  {/* Heading - First column value */}
                  <div
                    id={`row-${rowId}-heading`}
                    role="heading"
                    aria-level={3}
                    className="truncate"
                    aria-label={`${firstColumn.label}: ${row[firstColumn.key]}`}
                  >
                    {formatCellValue(row[firstColumn.key], firstColumn.format)}
                  </div>

                  {/* Summary - Next few primary columns */}
                  {summaryColumns.length > 0 && (
                    <div
                      className="text-muted-foreground flex w-full flex-wrap gap-x-4 gap-y-0.5"
                      role="group"
                      aria-label="Summary information"
                    >
                      {summaryColumns.map((column) => (
                        <span
                          key={column.key}
                          id={`row-${rowId}-${column.key}`}
                          className="flex min-w-0 gap-1 font-normal"
                          role="cell"
                          aria-label={`${column.label}: ${row[column.key]}`}
                        >
                          <span className="sr-only">{column.label}:</span>
                          <span aria-hidden="true">{column.label}:</span>
                          <span className="truncate">
                            {formatCellValue(row[column.key], column.format)}
                          </span>
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </AccordionTrigger>

              {/* Detail content - Remaining columns */}
              {detailColumns.length > 0 && (
                <AccordionContent
                  id={`row-${rowId}-details`}
                  role="region"
                  aria-labelledby={`row-${rowId}-heading`}
                  className="group data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-y-clip overflow-x-visible text-sm"
                >
                  <div className="px-4 pb-3 pt-0 space-y-2">
                    {detailColumns.map((column) => (
                      <div
                        key={column.key}
                        className="flex justify-between items-start gap-4"
                        role="row"
                      >
                        <span className="text-sm font-medium text-muted-foreground">
                          {column.label}
                        </span>
                        <span className="text-sm text-right">
                          {formatCellValue(row[column.key], column.format)}
                        </span>
                      </div>
                    ))}
                  </div>
                </AccordionContent>
              )}
            </AccordionItem>
          </Accordion>
        );
      })}
    </div>
  );

  return (
    <div
      className={cn(
        "w-full",
        className
      )}
      data-tool-ui-id={id}
      data-slot="data-table"
    >
      {tableView}
      {mobileView}
    </div>
  );
};

export { DataTable } from "./data-table";
export { parseSerializableDataTable } from "./schema";
export type { SerializableDataTable, Column, ColumnFormat, StatusConfig } from "./schema";

export interface StatusConfig {
  tone: "neutral" | "info" | "success" | "warning" | "danger";
  label?: string;
}

export interface ColumnFormat {
  kind: "text" | "status" | "date" | "boolean" | "number" | "delta" | "link" | "badge" | "array";

  // Status format
  statusMap?: Record<string, StatusConfig>;

  // Date format
  dateFormat?: "short" | "long" | "relative";

  // Number format
  numberFormat?: "integer" | "decimal" | "currency" | "percentage";

  // Delta format (for change indicators)
  deltaColors?: { positive?: string; negative?: string; neutral?: string };
  showSign?: boolean;

  // Link format
  linkTarget?: "_blank" | "_self";

  // Badge format
  badgeColorMap?: Record<string, string>;

  // Array format
  maxVisibleItems?: number;
  separator?: string;
}

export interface Column {
  key: string;
  label: string;
  priority?: "primary" | "secondary" | "tertiary";
  format?: ColumnFormat;
}

export interface SerializableDataTable {
  id: string;
  columns: Column[];
  data: Record<string, any>[];
  rowIdKey: string;
  caption?: string;
  striped?: boolean;
  compact?: boolean;
}

export function parseSerializableDataTable(input: any): SerializableDataTable {
  // Support both 'data' and 'rows' field names
  const tableData = input.data || input.rows || [];

  // Support both 'caption' and 'title' field names
  const caption = input.caption || input.title;

  // Auto-generate IDs for rows if not provided
  const dataWithIds = tableData.map((row: any) => ({
    ...row,
    id: row.id || crypto.randomUUID(),
  }));

  // Map column 'id' to 'key' and ensure each column has a unique key
  const columns = (input.columns || []).map((column: any) => ({
    ...column,
    key: column.key || column.id || crypto.randomUUID(),
  }));

  return {
    id: input.id || crypto.randomUUID(),
    columns,
    data: dataWithIds,
    rowIdKey: input.rowIdKey || "id",
    caption,
    striped: input.striped ?? true,
    compact: input.compact ?? false,
  };
}

"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import * as LucideIcons from "lucide-react";
import type { SerializableFileDownload } from "./schema";

interface FileDownloadProps extends SerializableFileDownload {
  className?: string;
}

export const FileDownload: FC<FileDownloadProps> = ({
  id,
  fileName,
  description,
  fileUrl,
  fileSize,
  icon = "File",
  className,
}) => {
  const Icon = (LucideIcons as any)[icon] || LucideIcons.File;

  const handleDownload = () => {
    // Create a temporary link element and trigger download
    const link = document.createElement('a');
    link.href = fileUrl;
    link.download = fileName;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div
      className={cn(
        "@container/file-download flex w-full max-w-md min-w-80 flex-col text-foreground",
        className
      )}
      data-slot="file-download"
      data-tool-ui-id={id}
      role="button"
      aria-label={`Download ${fileName}`}
    >
      <button
        onClick={handleDownload}
        className="bg-card/60 flex w-full flex-col overflow-hidden rounded-2xl border px-5 py-2.5 shadow-xs transition-colors cursor-pointer hover:bg-secondary"
      >
        <div className="flex items-start gap-3 py-1">
          <span className="flex h-6 items-center">
            <Icon
              className="text-primary size-4 shrink-0"
              aria-hidden="true"
            />
          </span>
          <div className="flex flex-col text-left flex-1">
            <span className="text-base leading-6 font-medium text-pretty @md/file-download:text-sm">
              {fileName}
            </span>
            {(description || fileSize) && (
              <span className="text-muted-foreground text-sm font-normal text-pretty">
                {description}
                {description && fileSize && " • "}
                {fileSize}
              </span>
            )}
          </div>
          <span className="flex h-6 items-center">
            <LucideIcons.Download
              className="text-muted-foreground size-4 shrink-0"
              aria-hidden="true"
            />
          </span>
        </div>
      </button>
    </div>
  );
};

export interface SerializableFileDownload {
  id: string;
  fileName: string;
  description?: string;
  fileUrl: string;
  fileSize?: string;
  icon?: string; // Lucide icon name, defaults to "File"
}

export function parseSerializableFileDownload(data: any): SerializableFileDownload {
  return {
    id: data.id || crypto.randomUUID(),
    fileName: data.fileName || "",
    description: data.description,
    fileUrl: data.fileUrl || "",
    fileSize: data.fileSize,
    icon: data.icon || "File",
  };
}

