  onResponseAction?: (actionId: string) => void;
}

export const LinkedInPost: FC<LinkedInPostProps> = ({
  post,
  className,
  onAction,
  responseActions,
  onResponseAction,
}) => {
  const formatDate = (dateString?: string) => {
    if (!dateString) return "";
    const date = new Date(dateString);
    const now = new Date();
    const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h`;
    if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)}d`;
    if (diffInSeconds < 2592000) return `${Math.floor(diffInSeconds / 604800)}w`;

    return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  };

  const formatNumber = (num?: number) => {
    if (!num || num === 0) return "";
    if (num < 1000) return num.toString();
    if (num < 1000000) return `${(num / 1000).toFixed(1)}K`;
    return `${(num / 1000000).toFixed(1)}M`;
  };

  const postUrl = `https://linkedin.com/feed/update/${post.id}`;

  return (
    <div className={cn("w-full max-w-[540px]", className)}>
      <div className="rounded-2xl border border-border bg-card overflow-hidden shadow-none">
        {/* Header */}
        <div className="p-4">
